head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. gridview_senseReader_WPF-929_(WSQ-2249).xml 실행한다.- Run gridview_senseReader_WPF-929_ (WSQ-2249) .xml
    //Verify 1. gridview_senseReader_WPF-929_(WSQ-2249).xml 실행된다.- gridview_senseReader_WPF-929_ (WSQ-2249) .xml is executed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_1_text').getValue() == '123456'", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Test step 2. 실행결과 name2의 필드에 값('123456')을 입력한다.- Enter the value ('123456') in the field of execution result name2.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('dataList1').setCellData(1,1,'123456')");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify 2. 정상적인 format값으로 123,456이 보여진다.(이전에는 1,23NaN,456 보여짐)- 123,456 is displayed as the normal format value (previously, 1,23NaN, 456 is shown)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_1_text').getValue() == '123456'", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.json1 = [{
            "col1": "1_1",
            "col2": "123456"
        },
        {
            "col1": "2_1",
            "col2": "345678"
        }
    ];
    dataList1.setJSON(json1);
    //Function unitTest
    //Create by Truong.Luu
    //Create date 18-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
